    #[test]
    fn blender_animation_paths_map_to_potter_model_paths() -> Result<()> {
        let mappings = BTreeMap::from([("Bone:Armature:Root".to_owned(), "bone_root".to_owned())]);
        for (blender, potter) in [
            ("location", "transform.translation"),
            ("rotation_euler", "transform.rotation_euler"),
            ("rotation_quaternion", "transform.rotation_quaternion"),
            ("scale", "transform.scale"),
            ("data.lens", "camera.lens_mm"),
            ("data.sensor_width", "camera.sensor_width_mm"),
            ("data.sensor_height", "camera.sensor_height_mm"),
            ("data.ortho_scale", "camera.ortho_scale"),
            ("data.clip_start", "camera.clip_start"),
            ("data.clip_end", "camera.clip_end"),
            ("data.shift_x", "camera.shift_x"),
            ("data.shift_y", "camera.shift_y"),
            ("data.dof.focus_distance", "camera.focus_distance"),
            ("data.dof.aperture_fstop", "camera.aperture_fstop"),
            ("data.energy", "light.energy"),
            ("data.color", "light.color"),
            ("data.spot_size", "light.spot_size"),
            ("data.spot_blend", "light.spot_blend"),
            ("data.shadow_soft_size", "light.shadow_soft_size"),
            ("data.size", "light.area_size"),
            ("data.size_y", "light.area_size_y"),
            ("data.angle", "light.sun_angle"),
            (
                "pose.bones[\"Root\"].location",
                "pose.bones[\"bone_root\"].location",
            ),
        ] {
            assert_eq!(potter_fcurve_path(blender, &mappings), potter);
        }
        assert_eq!(
            potter_fcurve_path_for_owner("color", &mappings, Some("LIGHT")),
            "light.color"
        );
        assert_eq!(
            potter_fcurve_path_for_owner("color", &mappings, None),
            "color"
        );
        let data_color =
            convert_fcurve_for_owner(&json!({"path":"color","index":1}), &mappings, Some("LIGHT"))?;
        assert_eq!(data_color.path, "light.color");
        assert_eq!(data_color.index, 1);
        let color = convert_fcurve(&json!({"path": "data.color", "index": 2}), &mappings)?;
        assert_eq!(color.path, "light.color");
        assert_eq!(color.index, 2);
        assert_eq!(
            potter_fcurve_path_for_owner("color", &mappings, Some("CAMERA")),
            "color"
        );
        for path in [
            "hide_render",
            "hide_viewport",
            "[\"property\"]",
            "nodes[\"Principled BSDF\"].inputs[\"Base Color\"].default_value",
        ] {
            assert_eq!(potter_fcurve_path(path, &mappings), path);
        }
        Ok(())
    }

    #[test]
    fn camera_and_light_animation_paths_require_the_matching_data_owner() {
        let camera = json!({
            "objects": [{"type": "CAMERA", "action": "CameraAction"}],
            "cameras": [],
            "lights": []
        });
        assert!(action_output_has_matching_owner(
            &camera,
            Some("CameraAction"),
            "camera.focus_distance",
            0
        ));
        assert!(!action_output_has_matching_owner(
            &camera,
            Some("CameraAction"),
            "light.spot_size",
            0
        ));
        assert!(driver_output_owner_matches(
            "camera.aperture_fstop",
            0,
            Some("CAMERA"),
            None,
            false
        ));
        assert!(!driver_output_owner_matches(
            "camera.aperture_fstop",
            0,
            Some("LIGHT"),
            None,
            false
        ));

        let light_data = json!({
            "objects": [],
            "cameras": [],
            "lights": [{"action": "LightAction"}]
        });
        assert!(action_output_has_matching_owner(
            &light_data,
            Some("LightAction"),
            "light.color",
            2
        ));
        assert!(!action_output_has_matching_owner(
            &light_data,
            Some("LightAction"),
            "camera.sensor_width_mm",
            0
        ));
        assert!(driver_output_owner_matches(
            "light.color",
            2,
            Some("LIGHT"),
            None,
            false
        ));
        assert!(!driver_output_owner_matches(
            "light.color",
            0,
            Some("CAMERA"),
            None,
            false
        ));
        let object = json!({
            "custom_properties": {"drive": 1.0, "vector": [1.0, 2.0]}
        });
        let object_action = json!({
            "objects": [{
                "type": "CAMERA",
                "action": "ObjectAction",
                "custom_properties": {"drive": 1.0, "vector": [1.0, 2.0]}
            }],
            "cameras": [{"action": "ObjectAction"}],
            "lights": []
        });
        assert!(action_output_has_matching_owner(
            &object_action,
            Some("ObjectAction"),
            "[\"drive\"]",
            0
        ));
        assert!(!action_output_has_matching_owner(
            &object_action,
            Some("ObjectAction"),
            "[\"drive\"]",
            1
        ));
        assert!(action_output_has_matching_owner(
            &object_action,
            Some("ObjectAction"),
            "[\"vector\"]",
            1
        ));
        assert!(!action_output_has_matching_owner(
            &object_action,
            Some("ObjectAction"),
            "[\"vector\"]",
            2
        ));
        assert!(!action_output_has_matching_owner(
            &object_action,
            Some("ObjectAction"),
            "data.[\"drive\"]",
            0
        ));
        assert!(driver_output_owner_matches(
            "[\"drive\"]",
            0,
            Some("CAMERA"),
            Some(&object),
            false
        ));
        assert!(driver_output_owner_matches(
            "[\"vector\"]",
            1,
            Some("CAMERA"),
            Some(&object),
            false
        ));
        assert!(!driver_output_owner_matches(
            "[\"vector\"]",
            2,
            Some("CAMERA"),
            Some(&object),
            false
        ));
        assert!(!driver_output_owner_matches(
            "[\"missing\"]",
            0,
            Some("CAMERA"),
            Some(&object),
            false
        ));
        assert!(!driver_output_owner_matches(
            "data.[\"drive\"]",
            0,
            Some("CAMERA"),
            Some(&object),
            true
        ));

        let data_custom_action = json!({
            "objects": [],
            "cameras": [{"action": "DataAction"}],
            "lights": []
        });
        assert!(!action_output_has_matching_owner(
            &data_custom_action,
            Some("DataAction"),
            "[\"drive\"]",
            0
        ));
        let losses = import_losses(&json!({
            "actions": [{
                "name": "DataAction",
                "fcurves": [{"path": "data.[\"drive\"]", "index": 0}]
            }],
            "objects": [],
            "cameras": [{"name": "CameraData", "action": "DataAction"}],
            "lights": []
        }));
        assert!(losses.iter().any(|loss| {
            loss.feature_id == "blender.animation.fcurve_non_transform_channel"
                && loss.reason.contains("Data-Block custom-property F-Curve")
        }));
    }

    #[test]
    fn blender_quaternion_components_convert_to_potter_xyzw() -> Result<()> {
        // Object and bone `rotation_quaternion` values reach this function already in Potter's
        // (x, y, z, w) order, so they must come back unchanged. Each input is a unit quaternion
        // with asymmetric components: swapping any two positions would change the result.
        let first = [0.6, 0.0, 0.8, 0.0];
        assert_eq!(
            blender_rotation(&json!({"rotation_quaternion": first}), "QUATERNION")?,
            first,
        );
        let norm = 0.95_f64.sqrt();
        let second = [0.1 / norm, 0.2 / norm, 0.3 / norm, 0.9 / norm];
        assert_eq!(
            blender_rotation(&json!({"rotation_quaternion": second}), "QUATERNION")?,
            second,
        );
        for (blender_index, potter_index) in [(0_i64, 3_u32), (1, 0), (2, 1), (3, 2)] {
            let curve = convert_fcurve(
                &json!({"path": "rotation_quaternion", "index": blender_index}),
                &BTreeMap::new(),
            )?;
            assert_eq!(curve.path, "transform.rotation_quaternion");
            assert_eq!(curve.index, potter_index);
        }
        Ok(())
    }

    #[test]
    fn blender_axis_angle_axis_is_normalized() -> Result<()> {
        // Blender normalizes `rotation_axis_angle`'s axis, so a Z axis of length 2 is a plain turn.
        let angle = std::f64::consts::FRAC_PI_2;
        let rotation = blender_rotation(
            &json!({"rotation_axis_angle": [angle, 0.0, 0.0, 2.0]}),
            "AXIS_ANGLE",
        )?;
        let expected = DQuat::from_axis_angle(glam::DVec3::Z, angle).to_array();
        for (actual, expected) in rotation.into_iter().zip(expected) {
            assert!(
                (actual - expected).abs() <= 1.0e-12,
                "expected {expected}, got {actual}"
            );
        }
        Ok(())
    }

