    fn approximately(actual: f64, expected: f64) -> bool {
        (actual - expected).abs() <= 1.0e-6
    }
    fn approximately_value(value: &Value, expected: f64) -> bool {
        value
            .as_f64()
            .is_some_and(|actual| approximately(actual, expected))
    }

