    #[test]
    fn blender_export_reports_unrepresentable_grease_pencil_fill_colors() -> Result<()> {
        let material_id = Id::new("fill_material")?;
        let data_id = Id::new("pencil_data")?;
        let second_data_id = Id::new("pencil_data_second")?;
        let mut doc = SceneDoc::new(uuid::Uuid::new_v4().to_string());
        doc.materials.insert(
            material_id.clone(),
            Material {
                name: "Fill Material".to_owned(),
                ..Material::default()
            },
        );
        let stroke = |id, fill, material| GreasePencilStroke {
            id,
            points: Vec::new(),
            material,
            cyclic: false,
            fill,
        };
        let data = |layer_id, strokes| DataBlock {
            data_type: "grease_pencil".to_owned(),
            grease_pencil: Some(GreasePencilData {
                layers: vec![GreasePencilLayer {
                    id: layer_id,
                    name: "Ink".to_owned(),
                    opacity: 1.0,
                    visible: true,
                    frames: vec![GreasePencilFrame {
                        frame: 1.0,
                        strokes,
                    }],
                }],
            }),
            ..DataBlock::default()
        };
        doc.data_blocks.insert(
            data_id,
            data(
                Id::new("ink_first")?,
                vec![
                    stroke(
                        Id::new("first")?,
                        Some([1.0, 0.0, 0.0, 1.0]),
                        Some(material_id.clone()),
                    ),
                    stroke(Id::new("unassigned")?, Some([0.0, 0.0, 1.0, 1.0]), None),
                    stroke(Id::new("unfilled_first")?, None, Some(material_id.clone())),
                ],
            ),
        );
        doc.data_blocks.insert(
            second_data_id,
            data(
                Id::new("ink_second")?,
                vec![
                    stroke(
                        Id::new("second")?,
                        Some([0.0, 1.0, 0.0, 1.0]),
                        Some(material_id.clone()),
                    ),
                    stroke(Id::new("unfilled")?, None, Some(material_id)),
                ],
            ),
        );

        let losses = export_losses(&doc);
        assert!(losses.iter().any(|loss| {
            loss.feature_id == "blender.grease_pencil.fill_color"
                && loss.reason.contains("no material")
        }));
        assert!(losses.iter().any(|loss| {
            loss.feature_id == "blender.grease_pencil.fill_color"
                && loss.reason.contains("different fill colors")
        }));
        assert!(losses.iter().any(|loss| {
            loss.feature_id == "blender.grease_pencil.fill_color"
                && loss.reason.contains("both filled and unfilled")
        }));
        Ok(())
    }

    fn custom_field_graph(carry_fields: bool) -> Result<NodeGroup> {
        let mut group = NodeGroup::new("Custom Field Graph", GraphKind::Shader);
        group.nodes.insert(
            Id::new("principled")?,
            GraphNode::new("ShaderNodeBsdfPrincipled"),
        );
        group
            .nodes
            .insert(Id::new("output")?, GraphNode::new("OutputMaterial"));
        group.links.push(GraphLink {
            from_node: Id::new("principled")?,
            from_socket: "BSDF".to_owned(),
            to_node: Id::new("output")?,
            to_socket: "Surface".to_owned(),
        });
        if carry_fields {
            let mut displacement = GraphNode::new("ShaderNodeDisplacement");
            displacement
                .inputs
                .insert("Midlevel".to_owned(), json!(0.25));
            displacement.inputs.insert("Scale".to_owned(), json!(2.5));
            group.nodes.insert(Id::new("displacement")?, displacement);
            group.links.push(GraphLink {
                from_node: Id::new("displacement")?,
                from_socket: "Displacement".to_owned(),
                to_node: Id::new("output")?,
                to_socket: "Displacement".to_owned(),
            });
            let mut volume = GraphNode::new("ShaderNodeVolumePrincipled");
            volume.inputs.insert("Density".to_owned(), json!(0.4));
            volume
                .inputs
                .insert("Color".to_owned(), json!([0.1, 0.2, 0.3, 1.0]));
            volume.inputs.insert("Anisotropy".to_owned(), json!(0.35));
            group.nodes.insert(Id::new("volume")?, volume);
            group.links.push(GraphLink {
                from_node: Id::new("volume")?,
                from_socket: "Volume".to_owned(),
                to_node: Id::new("output")?,
                to_socket: "Volume".to_owned(),
            });
        }
        Ok(group)
    }

    /// A cube with one Geometry Nodes modifier whose group holds two bake nodes and a transform node.
    fn nodes_bake_modifier(bakes: Value) -> Result<SceneDoc> {
        let mut doc = SceneDoc::new(uuid::Uuid::new_v4().to_string());
        let mut group = NodeGroup::new("Geometry", GraphKind::Geometry);
        for bake in ["bake_main", "bake_disk"] {
            group
                .nodes
                .insert(Id::new(bake)?, GraphNode::new("GeometryNodeBake"));
        }
        group.nodes.insert(
            Id::new("transform")?,
            GraphNode::new("GeometryNodeTransform"),
        );
        doc.node_groups.insert(Id::new("group_geo")?, group);
        let mut cube = test_node("Cube", "mesh_cube", None, None)?;
        cube.modifiers.push(Modifier {
            id: Id::new("geo")?,
            modifier_type: "nodes".to_owned(),
            name: "Geo".to_owned(),
            enabled: true,
            show_viewport: true,
            show_render: true,
            params: Map::from_iter([
                ("node_group".to_owned(), json!("group_geo")),
                ("bakes".to_owned(), bakes),
            ]),
            baked_ocean_cache: None,
            binding_data: None,
            runtime: crate::model::ModifierRuntime::default(),
        });
        doc.nodes.insert(Id::new("cube")?, cube);
        Ok(doc)
    }

    #[test]
    fn export_losses_report_nodes_bake_payloads_and_unmapped_entries() -> Result<()> {
        let doc = nodes_bake_modifier(json!({
            "bake_main": {"bake_mode": "STILL", "bake_target": "DISK", "directory": "//bakes"},
            "bake_disk": {"storage": "disk"},
            "transform": {"bake_mode": "STILL"},
            "ghost": {"frame_start": 1}
        }))?;
        let losses = export_losses(&doc);
        let bake_losses = losses
            .iter()
            .filter(|loss| loss.feature_id.starts_with("blender.modifier.nodes_bake"))
            .map(|loss| (loss.feature_id.as_str(), loss.data_id.as_deref()))
            .collect::<Vec<_>>();
        assert_eq!(
            bake_losses,
            [
                ("blender.modifier.nodes_bake_payload", Some("geo")),
                ("blender.modifier.nodes_bake_unmapped", Some("geo")),
                ("blender.modifier.nodes_bake_unmapped", Some("geo")),
            ]
        );
        assert!(losses.iter().any(|loss| {
            loss.feature_id == "blender.modifier.nodes_bake_payload"
                && loss.reason.contains("disk payload of bake node bake_disk")
        }));
        assert!(losses.iter().any(|loss| {
            loss.feature_id == "blender.modifier.nodes_bake_unmapped"
                && loss.reason.contains("bake entry transform ")
        }));
        assert!(losses.iter().any(|loss| {
            loss.feature_id == "blender.modifier.nodes_bake_unmapped"
                && loss.reason.contains("bake entry ghost ")
        }));
        Ok(())
    }

